  const button=state.phase==='player'||state.phase==='finished'?null:[...flow.querySelectorAll(selector)].find(el=>!el.disabled&&el.getClientRects().length&&!el.closest('details:not([open])'));
  const target=button||flow.querySelector('h2')||flow,rect=target.getBoundingClientRect(),viewport=window.visualViewport,top=viewport?.offsetTop||0,height=viewport?.height||innerHeight,gap=Math.min(48,Math.max(16,height*.08));
